export type AiTask =
  /** Mends what PDF conversion broke in the text, heading and quote cards of a note the person may edit, as changes to apply (ADR-0063) */
  | 'CLEAN_UP'
  /** Needs the right to copy the note (ADR-0025) */
  | 'CREATE_NOTES'
  /** On the note's code cards */
  | 'EXPLAIN_CODE'
  | 'EXPLAIN_SIMPLY'
  | 'FIND_MISTAKES'
  | 'FLASHCARDS'
  | 'KEY_CONCEPTS'
  /** Needs the right to copy the note (ADR-0025) */
  | 'OUTLINE_TO_NOTE'
  | 'PRACTICE_QUESTIONS'
  /** The person's own note's rough words and photos, as a structured note (ADR-0062) */
  | 'QUICK_NOTE'
  | 'QUIZ'
  | 'REVISION_SHEET'
  | 'SUMMARIZE'
  /** One audio or video card (cardIds), as a text card to keep (ADR-0062) */
  | 'TRANSCRIBE'
  | 'TRANSLATE';

export type AiTaskRouteInput = {
  task: string;
};

/** Why AI is not answering */
export type AiUnavailableReason =
  /** This month's AI budget is used up; it resumes next month */
  | 'BUDGET'
  /** Not switched on in this environment */
  | 'NOT_CONFIGURED'
  /** The model failed several times in a row; it is tried again shortly */
  | 'PROVIDER_DOWN';

