/** Where Ask AI looks, always within what the asker may read */
export type AskAiScope =
  /** The asker's published notes */
  | 'MY_NOTES'
  /** Notes shared with the asker's groups and classes */
  | 'MY_PLACES'
  | 'PUBLIC'
  /** One note, as the asker reads it (the draft for its owner and editors) */
